import {syntheticV12} from './jev-v12'
import {syntheticIndependent} from './independent-jev'
import {negativeUuid} from './negative-validation'
import {V13_CASES} from './jev-v13-cases'
import {V12_CONFIG} from '../../supabase/functions/_shared/jev-v12-config'
import {V13_CONFIG} from '../../supabase/functions/_shared/jev-v13-config'
import {V13_FIRST_SOURCE,V13_SECOND_SOURCE,V13_BENCH_CONFIG,firstDevelopmentSource,secondDevelopmentSource,prepareV13,freshV13Source,type V13Task,type V13Audit,type V13Run,type V13FreshInput} from '../../supabase/functions/_shared/jev-v13-core'
import {negativeHash} from '../../supabase/functions/_shared/negative-validation-core'
import {postgresJsonbText} from '../../supabase/functions/_shared/independent-jev-core'
export async function syntheticV13(kind:'first'|'second'|'fresh'='first'){
 const f=await syntheticV12();f.run.id=V13_FIRST_SOURCE;const oldTasks:V13Task[]=f.v12Tasks.map(t=>({...t,run_id:V13_FIRST_SOURCE,model_version:'v12',question_set:V12_CONFIG.question_set,review_alias:'r'+f.prepared.items.find(i=>i.review_id===t.review_id)!.position,analysis_text_sha256:f.prepared.items.find(i=>i.review_id===t.review_id)!.analysis_text_sha256}));let source=await firstDevelopmentSource(f.run,oldTasks),freshInput:V13FreshInput|undefined;
 if(kind==='second'||kind==='fresh'){const g=await syntheticIndependent();g.run.id=V13_SECOND_SOURCE;const paired=g.items.slice(0,kind==='second'?31:32).map(i=>i.review_id),base=g.tasks.filter(t=>t.model_version==='v12').map(t=>({...t,run_id:g.run.id,model_version:'v12' as const}));source=await secondDevelopmentSource(g.run,base,paired,[]);
 if(kind==='second'){const audits:V13Audit[]=V13_CASES.map((c,n)=>{const i=source.items[n],ref=source.reference.find(r=>r.review_id===i.review_id&&r.theme_key===c.theme)!;return {audit_id:negativeUuid(130100+n),run_id:source.id,review_id:i.review_id,theme_key:c.theme,analysis_text_sha256:i.analysis_text_sha256,initial_ai_choice:ref.choice,reviewed_ai_choice:c.choice,verdict:c.verdict,error_kind:c.choice==='absent'?'false_positive':'false_negative',annotation_source:'synthetic-ai-audit',scoring_use:'diagnostic_only_no_sealed_reference_change',rationale_fr:'Synthetic '+c.id,has_translation_concern:n===10,created_at:'2026-10-10'}});source.audits=audits}
 else {const items=source.items.map(i=>({...i,establishment_id:negativeUuid(88777)}));freshInput={id:negativeUuid(131333),organization_id:source.organization_id,name:'Synthetic fresh only',items,reference:source.reference,configuration_id:V13_CONFIG.question_set,source_kind:'fresh_blind_ai',blind_to_predictions:true,reference_created_at:'2026-10-09T01:00:00Z',sealed_at:'2026-10-09T02:00:00Z',dataset_sha256:await negativeHash(postgresJsonbText(items)),reference_sha256:await negativeHash(postgresJsonbText(source.reference))};source=await freshV13Source(freshInput,[],'2026-10-08T00:00:00Z')}
 }
 const prepared=await prepareV13(source,{input:.042,output:0}),run:V13Run={id:negativeUuid(131313),source_id:source.id,source_kind:source.kind,organization_id:source.organization_id,config:V13_BENCH_CONFIG,prepared,status:'completed',created_at:'2026-10-10',started_at:'2026-10-10T01:00:00Z',completed_at:'2026-10-10T01:01:00Z',error_code:null},tasks:V13Task[]=source.kind==='fresh_blind_ai'?source.items.flatMap((i,n)=>(['v12','v13'] as const).flatMap((model_version,m)=>[1,2,3].map(repeat=>{const d=oldTasks[0];return {...structuredClone(d),id:negativeUuid(140000+n*6+m*3+repeat),run_id:run.id,review_id:i.review_id,analysis_text_sha256:i.analysis_text_sha256,review_alias:'r'+i.position,model_version,repeat,question_set:run.config[model_version].question_set}}))):source.baseline.map((t,n)=>({...structuredClone(t),id:negativeUuid(150000+n),run_id:run.id,model_version:'v13',question_set:V13_CONFIG.question_set}));return {source,prepared,run,tasks,freshInput}
}
